#include "risk/analytics.hpp"
#include <cmath>
#include <fstream>
#include <iomanip>
#include <iostream>
#include <stdexcept>
static double number(const std::string& s){size_t n;double x=std::stod(s,&n);if(n!=s.size()||!std::isfinite(x))throw std::runtime_error("Invalid numeric argument");return x;}
static void value(std::ostream& o,double x){if(std::isfinite(x))o<<x;else o<<"N/A";}
int main(int argc,char** argv){try{risk::Config c;std::string path,export_path;for(int i=1;i<argc;++i){std::string arg=argv[i];if(arg=="--help"){std::cout<<"dashboard [CSV] [--periods N] [--rf RATE] [--confidence P] [--window N] [--export FILE]\n";return 0;}if(arg.rfind("--",0)==0){if(++i==argc)throw std::runtime_error("Missing option value");std::string v=argv[i];if(arg=="--export")export_path=v;else if(arg=="--periods")c.periods=number(v);else if(arg=="--rf")c.rf=number(v);else if(arg=="--confidence")c.confidence=number(v);else if(arg=="--window"){double x=number(v);if(x<2||x>100000000||std::floor(x)!=x)throw std::runtime_error("Invalid window");c.window=static_cast<size_t>(x);}else throw std::runtime_error("Unknown option: "+arg);}else if(path.empty())path=arg;else throw std::runtime_error("Unexpected argument");}if(path.empty()){std::cout<<"Enter CSV file name or path: ";std::getline(std::cin,path);}auto a=risk::load_csv(path);auto z=risk::analyze(a,c);std::cout<<std::setprecision(17);for(auto& kv:z.metrics){std::cout<<kv.first<<'=';value(std::cout,kv.second);std::cout<<'\n';}if(!export_path.empty()){if(export_path==path)throw std::runtime_error("Export must not overwrite input");std::ofstream f(export_path);f<<std::setprecision(17)<<"date,price,simple_return,log_return,drawdown,rolling_volatility\n";for(size_t i=0;i<a.size();++i){f<<a[i].date<<','<<a[i].price<<',';if(i)value(f,z.returns[i-1]);else f<<"N/A";f<<',';if(i)value(f,z.logs[i-1]);else f<<"N/A";f<<','<<z.drawdown[i]<<',';value(f,z.rolling[i]);f<<'\n';}f.close();if(!f)throw std::runtime_error("Export failed");}return 0;}catch(const std::exception& e){std::cerr<<"Error: "<<e.what()<<'\n';return 1;}}
